export type Values={title:string;description:string;priority:"LOW"|"MEDIUM"|"CRITICAL";assignee:string|null;estimateHours:number|""};
export type Errors<T>=Partial<Record<keyof T,string>>;
export type Touched<T>=Partial<Record<keyof T,boolean>>;
export const emptyValues=():Values=>({title:"",description:"",priority:"MEDIUM",assignee:null,estimateHours:""});
export function validate(values:Values):Errors<Values>{const errors:Errors<Values>={};const title=values.title.trim();if(!title)errors.title="Tytuł jest wymagany.";else if(title.length<5)errors.title="Minimum 5 znaków.";else if(title.length>120)errors.title="Maksimum 120 znaków.";if(values.assignee!==null&&!["anna","piotr","kasia"].includes(values.assignee))errors.assignee="Wybierz osobę z listy.";if(values.estimateHours!==""&&(!Number.isFinite(values.estimateHours)||values.estimateHours<0))errors.estimateHours="Podaj skończony, nieujemny czas.";if(values.priority==="CRITICAL"&&!values.description.trim())errors.description="Ticket krytyczny wymaga opisu.";return errors;}
export function visibleError<T>(errors:Errors<T>,touched:Touched<T>,submitted:boolean,field:keyof T):string|undefined{return touched[field]||submitted?errors[field]:undefined;}
export const ORDER:ReadonlyArray<keyof Values>=["title","description","assignee","estimateHours"];
export function firstError(errors:Errors<Values>):keyof Values|undefined{return ORDER.find(field=>Boolean(errors[field]));}
